<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gojo · rules across domains and revisable construction</title><style>
:root{--paper:#f7f5ee;--ink:#25434b;--muted:#65767a;--line:#cbd5ce;--teal:#2c6971;--white:#fffdf7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}main{max-width:1540px;margin:auto;padding:28px 30px 45px}h1,h2,h3{font-family:Georgia,serif;font-weight:500;line-height:1.2}h1{font-size:clamp(31px,4vw,47px);max-width:1100px;margin:8px 0 16px}h2{font-size:27px;margin:0 0 13px}h3{font-size:21px;margin:0}p{margin:8px 0 16px}.intro{max-width:1050px;font-size:18px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:12px;color:var(--muted)}a{color:var(--teal);text-underline-offset:3px}.links{display:flex;gap:20px;flex-wrap:wrap;font-size:14px;margin:18px 0 24px}.tabs{display:flex;gap:10px;margin-bottom:19px;border-bottom:1px solid var(--line);padding-bottom:12px}button,select{font:inherit;color:inherit;max-width:100%;border:1px solid #aebfb8;border-radius:5px;background:var(--white);padding:9px 12px}button{cursor:pointer}button:hover{background:#e7eee8}button[aria-selected=true]{background:var(--ink);color:var(--white);border-color:var(--ink)}button:focus-visible,select:focus-visible{outline:3px solid #c9a266;outline-offset:3px}.controls{display:grid;grid-template-columns:1.15fr 1.5fr .9fr 1fr auto;gap:14px;align-items:end;background:#e9ede5;padding:17px;border:1px solid var(--line);border-radius:7px}label{display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:650}select{width:100%;font-size:14px;min-width:0}.check{flex-direction:row;align-items:center;gap:8px;padding:10px 0;white-space:nowrap}.check input{width:17px;height:17px;accent-color:var(--teal)}.explanation{background:var(--white);border:1px solid var(--line);padding:19px 21px;border-radius:7px;margin:20px 0}.explanation p{max-width:1120px}.muted,small{color:var(--muted)}.hint{padding:12px 15px;background:#edf0e8;border-left:3px solid #789b91;font-size:14px}.summary{display:flex;gap:18px;flex-wrap:wrap;font-size:14px}.summary strong{font-size:25px;font-weight:500;margin-right:6px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:var(--white);border:1px solid var(--line);border-radius:7px;overflow:hidden;min-width:0;display:flex;flex-direction:column}.card.excluded{border-style:dashed}.card-head{display:flex;gap:10px;justify-content:space-between;align-items:flex-start;padding:14px 15px 8px}.card h3{font-size:20px}.id{display:block;font:12px system-ui,sans-serif;color:var(--muted);margin-bottom:4px}.pill{border:1px solid #aabcb7;background:#edf2ec;border-radius:15px;padding:3px 8px;font-size:11px;max-width:145px;flex-shrink:0;line-height:1.4}.excluded .pill{border-color:#bdb3a4;background:#eeeae3;color:#655b4d}.open .pill{background:#f4eada;border-color:#c8ac80;color:#705a39}.card img{display:block;width:100%;height:205px;object-fit:contain;background:#faf8ee}.card-body{padding:13px 15px;flex:1;display:flex;flex-direction:column}.card-body p{font-size:13px;margin:0 0 10px}.inspect{font-size:13px;align-self:flex-start;margin-top:auto;padding:7px 11px}.inspection{padding:20px;border:2px solid #7c9b92;border-radius:7px;background:var(--white);margin:20px 0}.section-head{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.section-head button{font-size:13px;padding:6px 10px}.inspection img{height:250px;width:100%;object-fit:contain;background:#faf8ee}.table-wrap{overflow-x:auto;max-width:100%}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px 8px;border-bottom:1px solid #e0e4dd;text-align:left;vertical-align:top}th{background:#edf0e8;font-weight:650}.fact{font-weight:650;white-space:nowrap}details{margin-top:10px}summary{cursor:pointer;font-size:14px;font-weight:600}.empty{padding:30px;border:1px dashed var(--line);color:var(--muted);grid-column:1/-1}.generation-controls{grid-template-columns:1.5fr 1.5fr}.comparisons{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:18px 0}.comparisons figure{margin:0;min-width:0;padding:12px;background:var(--white);border:1px solid var(--line);border-radius:6px}.comparisons figcaption{font-size:13px;font-weight:650;margin-bottom:8px}.comparisons img{display:block;width:100%;height:260px;object-fit:contain;background:#faf8ee}.comparisons small{display:block;font-size:12px;margin-top:8px}.ghost{opacity:.48}.no-output{height:260px;display:grid;place-content:center;text-align:center;border:1px dashed var(--line);color:var(--muted);padding:25px}.read-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:20px 0}.read-box{border-left:3px solid #8ba59b;padding:10px 13px;background:#eef1e9;font-size:14px}.read-box strong{display:block;font-size:18px;margin-top:5px}.timeline{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:18px 0 23px}.stage-button{padding:12px;text-align:left;font-size:13px;border-color:var(--line);min-width:0}.stage-button[aria-selected=true]{background:#e6eee7;color:var(--ink);border:2px solid #6b9085;padding:11px}.stage-button strong{display:block;margin-bottom:6px}.stage-button span{display:block;color:var(--muted);font-size:12px}.stage-button img{width:100%;height:88px;object-fit:contain;margin:7px 0;background:#faf8ee}.proposal-selected{background:#edf2ea}.scroll-note{font-size:12px;color:var(--muted);margin:8px 0}.findings{margin-top:35px;padding-top:22px;border-top:1px solid var(--line)}.findings li{margin:9px 0;font-size:14px}footer{font-size:13px;color:var(--muted);margin-top:28px}[hidden]{display:none!important}
